const body = $input.first().json.body || {};
const message = body.message || {};
const messageType = message.type || '';
if (messageType !== 'end-of-call-report') {
  return [{ json: { is_eoc: false } }];
}

const call = message.call || {};
const sd = message.analysis?.structuredData || {};

// --- existing fields (unchanged behaviour) ---
const vapiCallId = call.id || '';
const summary = message.analysis?.summary || message.artifact?.messages?.map(m => m.content || '').join(' ').substring(0, 500) || 'No summary available';
const sentiment = sd.sentiment || 'neutral';
const callerPhone = call.customer?.number || '';
const callerName = sd.callerName || 'Unknown';
const validSentiments = ['positive', 'neutral', 'negative'];

// --- outcome fields: every one defaults to null when VAPI omits it ---
// null = "not scored". Never default a missing boolean to false: that would
// count an unanalysed call as "not contained" / "not escalated".
const toBool = (v) => (v === true || v === 'true') ? true : (v === false || v === 'false') ? false : null;
const toText = (v, max) => (typeof v === 'string' && v.trim()) ? v.trim().substring(0, max) : null;
const firstBool = (...vals) => { for (const v of vals) { const b = toBool(v); if (b !== null) return b; } return null; };

const validStatuses = ['approved', 'pending', 'requires_documentation', 'not_found'];
const claimStatus = validStatuses.includes(sd.claimStatus) ? sd.claimStatus : null;

// Claim numbers end up in a PostgREST filter later, so only allow a strict charset.
const rawClaim = toText(sd.claimNumber, 40);
const claimNumber = (rawClaim && /^[A-Za-z0-9-]{3,40}$/.test(rawClaim)) ? rawClaim.toUpperCase() : null;

// Duration: VAPI's own number if present, else derive it from the timestamps.
let duration = Number(message.durationSeconds ?? call.durationSeconds);
if (!Number.isFinite(duration)) {
  const started = Date.parse(message.startedAt || call.startedAt || '');
  const ended = Date.parse(message.endedAt || call.endedAt || '');
  duration = (Number.isFinite(started) && Number.isFinite(ended)) ? (ended - started) / 1000 : NaN;
}
const durationSeconds = (Number.isFinite(duration) && duration >= 0) ? Math.round(duration) : null;

// Caller ID digits (11 digits for US numbers), used by pre-call-context to find
// "this caller's last call". Same normalisation rules as lookup-caller.
let callerDigits = String(callerPhone || message.customer?.number || '').replace(/\D/g, '');
if (callerDigits.length === 10) callerDigits = '1' + callerDigits;
if (callerDigits.length < 10) callerDigits = '';

return [{
  json: {
    is_eoc: true,
    caller_name: callerName,
    phone_number: callerPhone,
    summary: summary,
    sentiment: validSentiments.includes(sentiment) ? sentiment : 'neutral',
    timestamp: new Date().toISOString(),
    vapi_call_id: vapiCallId,
    call_reason: toText(sd.callReason, 200),
    authenticated: toBool(sd.authenticated),
    claim_number: claimNumber,
    claim_status: claimStatus,
    resolved_without_human: toBool(sd.resolvedWithoutHuman),
    // Older analyses only have 'escalated' / 'callbackPromised': use them as fallbacks.
    escalation_requested: firstBool(sd.escalationRequested, sd.escalated),
    follow_up_needed: firstBool(sd.followUpNeeded, sd.callbackPromised),
    follow_up_reason: toText(sd.followUpReason, 300),
    duration_seconds: durationSeconds,
    ended_reason: toText(message.endedReason || call.endedReason, 100),
    caller_phone_digits: callerDigits || null
  }
}];

// The create above is rejected when log_interaction already wrote this call's row
// (UNIQUE vapi_call_id). That row has no outcome data, so patch the outcome
// columns onto it. Summary / sentiment / caller_name written by the LLM are kept.
const parsed = $('Strip Meta').first().json;
if (!parsed.vapi_call_id) return [];   // no call id: nothing safe to match on

const OUTCOME_KEYS = [
  'call_reason', 'authenticated', 'claim_number', 'claim_status',
  'resolved_without_human', 'escalation_requested', 'follow_up_needed',
  'follow_up_reason', 'duration_seconds', 'ended_reason', 'caller_phone_digits'
];
const patch = { vapi_call_id: parsed.vapi_call_id };
for (const k of OUTCOME_KEYS) patch[k] = parsed[k] ?? null;
return [{ json: patch }];

// Deploy-time settings. scripts/deploy-n8n.sh replaces these placeholders from .env;
// an unresolved or empty value means "not configured" and the action is skipped.
const ALERT_EMAIL_TO = '__ALERT_EMAIL_TO__';
const ALERT_EMAIL_FROM = '__ALERT_EMAIL_FROM__';
const TWILIO_FROM_NUMBER = '__TWILIO_FROM_NUMBER__';
const SMTP_CREDENTIAL_ID = '__N8N_SMTP_CREDENTIAL_ID__';
const TWILIO_CREDENTIAL_ID = '__N8N_TWILIO_CREDENTIAL_ID__';
const configured = (v) => typeof v === 'string' && v.trim() !== '' && !v.startsWith('__');

const parsed = $('Strip Meta').first().json;
// Merge Outcomes returns the stored row. Prefer it: on the happy path its sentiment
// is the one the LLM logged during the call. Fall back to what we parsed if the
// update failed (for example migration 007 not applied yet).
const stored = $input.all().map(i => i.json)
  .find(r => r && r.id && r.vapi_call_id === parsed.vapi_call_id) || {};
const pick = (k) => (stored[k] !== undefined && stored[k] !== null) ? stored[k] : parsed[k];

const escalationRequested = pick('escalation_requested') === true;
const negative = stored.sentiment === 'negative' || parsed.sentiment === 'negative';
const followUpNeeded = pick('follow_up_needed') === true;
const resolved = pick('resolved_without_human') === true;
const authenticated = pick('authenticated') === true;
const followUpReason = pick('follow_up_reason') || '';
const claim = String(pick('claim_number') || '').toUpperCase();
const claimOk = /^[A-Z0-9-]{3,40}$/.test(claim);

const doEscalation = escalationRequested || negative;
const triggers = [];
if (escalationRequested) triggers.push('caller asked for a human');
if (negative) triggers.push('negative sentiment');

const twilioConfigured = configured(TWILIO_FROM_NUMBER) && configured(TWILIO_CREDENTIAL_ID);
const alertConfigured = configured(ALERT_EMAIL_TO) && configured(ALERT_EMAIL_FROM) && configured(SMTP_CREDENTIAL_ID);

return [{
  json: {
    vapi_call_id: parsed.vapi_call_id,
    do_escalation: doEscalation,
    escalation_trigger: triggers.join(' + '),
    escalation_reason: doEscalation ? (followUpReason || triggers.join(' + ')) : '',
    send_alert: doEscalation && alertConfigured,
    alert_email_to: alertConfigured ? ALERT_EMAIL_TO : '',
    alert_email_from: alertConfigured ? ALERT_EMAIL_FROM : '',
    do_sms: resolved && authenticated && claimOk && twilioConfigured,
    sms_from: twilioConfigured ? TWILIO_FROM_NUMBER : '',
    claim_number: claimOk ? claim : '',
    do_callback: followUpNeeded,
    callback_reason: followUpNeeded ? (followUpReason || 'Follow-up needed (no reason captured)') : ''
  }
}];

