// The SMS goes ONLY to the phone number stored on the customers row for this claim.
// Never to the caller ID, never to a number the caller said on the call.
const d = $('Decide Actions').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.id);
if (rows.length !== 1) return [];                       // no row, or ambiguous
const r = rows[0];
if (String(r.claim_number || '').toUpperCase() !== d.claim_number) return [];
if (!/^\+[1-9]\d{9,14}$/.test(r.phone_number || '')) return [];   // must be E.164
if (!d.sms_from) return [];

// Status comes from the database row, not from what the LLM thinks it said.
const lines = {
  approved: 'has been approved.',
  pending: 'is under review. We will let you know when there is an update.',
  requires_documentation: 'needs additional documentation before we can proceed. Please call us if you need the list of documents.'
};
const line = lines[r.claim_status];
if (!line) return [];

return [{
  json: {
    to: r.phone_number,
    from: d.sms_from,
    body: 'Observe Insurance: your claim ' + r.claim_number + ' ' + line + ' This number is not monitored.',
    vapi_call_id: d.vapi_call_id
  }
}];
